"""install_skill.py — 安装 Skill Package 到员工 {RUNTIME_HOME}/skills/。

用法：
  install_skill.py --list                     列出可安装与已安装技能
  install_skill.py <skill_dir>                安装指定技能目录（含 manifest.json）
  install_skill.py --builtin <name>           从代码内置仓库复制（便于定制覆盖）
  install_skill.py <...> --force              覆盖同名已安装技能

探索期产出的技能（explore/output/<name>/）经人工审核后由本脚本安装。
仅使用 Python3 标准库。
"""
import argparse
import json
import shutil
import sys
import time
from pathlib import Path

BASE_DIR = Path(__file__).resolve().parent.parent       # agent_runtime/
sys.path.insert(0, str(BASE_DIR.parent))                # backend/

from agent_runtime.core.config import RuntimeConfig      # noqa: E402

REGISTRY_NAME = '_registry.json'


def _load_user_registry(config):
    reg_file = config.skills_user_dir / REGISTRY_NAME
    if reg_file.exists():
        try:
            return json.loads(reg_file.read_text(encoding='utf-8'))
        except (ValueError, OSError):
            pass
    return {'skills': {}, 'version': 1}


def _save_user_registry(config, data):
    (config.skills_user_dir / REGISTRY_NAME).write_text(
        json.dumps(data, indent=2, ensure_ascii=False), encoding='utf-8')


def _is_skill_dir(d):
    return d.is_dir() and (d / 'manifest.json').exists()


def cmd_list(config):
    print('=== 代码内置技能（%s）===' % config.skills_builtin_dir)
    for d in sorted(Path(config.skills_builtin_dir).iterdir()):
        if _is_skill_dir(d):
            print('  %s' % d.name)
    explore_out = BASE_DIR / 'explore' / 'output'
    print('=== 探索产出的待审核技能（%s）===' % explore_out)
    found = False
    if explore_out.exists():
        for d in sorted(explore_out.iterdir()):
            if _is_skill_dir(d):
                print('  %s' % d.name)
                found = True
    if not found:
        print('  （无）')
    print('=== 已安装的员工技能（%s）===' % config.skills_user_dir)
    registry = _load_user_registry(config)
    if registry['skills']:
        for name, info in sorted(registry['skills'].items()):
            print('  %s (version=%s installed=%s)' % (
                name, info.get('version', '?'), info.get('installed_at', '?')))
    else:
        print('  （无）')


def install(config, src_dir, force=False):
    src = Path(src_dir)
    if not _is_skill_dir(src):
        print('错误: %s 不是有效的技能目录（缺少 manifest.json）' % src)
        return 1
    manifest = json.loads((src / 'manifest.json').read_text(encoding='utf-8'))
    name = manifest.get('name') or src.name
    dest = config.skills_user_dir / name
    if dest.exists():
        if not force:
            print('错误: 技能 %s 已安装，使用 --force 覆盖' % name)
            return 1
        shutil.rmtree(dest)
    shutil.copytree(src, dest)
    registry = _load_user_registry(config)
    registry['skills'][name] = {
        'version': manifest.get('version', '0.1.0'),
        'description': manifest.get('description', ''),
        'installed_at': time.strftime('%Y-%m-%d %H:%M:%S'),
    }
    _save_user_registry(config, registry)
    print('技能 %s 已安装到 %s' % (name, dest))
    return 0


def main():
    parser = argparse.ArgumentParser(description='安装 Skill Package 到员工工位')
    parser.add_argument('source', nargs='?', help='技能目录路径或内置技能名')
    parser.add_argument('--builtin', metavar='NAME',
                        help='从代码内置仓库安装指定技能')
    parser.add_argument('--list', action='store_true', help='列出技能')
    parser.add_argument('--force', action='store_true', help='覆盖同名技能')
    args = parser.parse_args()

    config = RuntimeConfig(agent_id='cli')
    config.ensure_dirs()

    if args.list or not (args.source or args.builtin):
        cmd_list(config)
        return 0

    if args.builtin:
        src = Path(config.skills_builtin_dir) / args.builtin
    else:
        src = Path(args.source)
        if not src.exists() and _is_skill_dir(
                Path(config.skills_builtin_dir) / args.source):
            src = Path(config.skills_builtin_dir) / args.source
    return install(config, src, force=args.force)


if __name__ == '__main__':
    sys.exit(main())
